package nl.jumbospeur.game;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.Intent;import com.google.zxing.integration.android.*;
public class Main extends Activity { WebView web; public void onCreate(Bundle b){super.onCreate(b); web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return true;}});web.addJavascriptInterface(this,"Game");web.loadUrl("file:///android_asset/index.html");} @JavascriptInterface public void scan(){runOnUiThread(()->new IntentIntegrator(this).setBeepEnabled(false).setOrientationLocked(false).setPrompt("Richt op een productbarcode").initiateScan());} protected void onActivityResult(int r,int c,Intent i){super.onActivityResult(r,c,i);IntentResult res=IntentIntegrator.parseActivityResult(r,c,i);if(res!=null && res.getContents()!=null)web.evaluateJavascript("barcode("+org.json.JSONObject.quote(res.getContents())+")",null);} }
